using CustomCodeFramework.Core.Results;using CustomCodeFramework.Cqrs.Commands;using CustomCodeFramework.Persistence.Abstractions;using Dhole.Content.Application.Abstractions.Auditing;using Dhole.Content.Application.Abstractions.Repositories;using Dhole.Content.Application.Abstractions.Slugs;using Dhole.Content.Application.Auditing;using Dhole.Content.Domain.Shared;namespace Dhole.Content.Application.Taxonomies.UpdateTaxonomy;public sealed class UpdateTaxonomyCommandHandler(ITaxonomyTermRepository repo,ISlugGenerator slugs,IContentAuditService audit,IUnitOfWork uow):ICommandHandler<UpdateTaxonomyCommand,Result>{public async Task<Result> HandleAsync(UpdateTaxonomyCommand c,CancellationToken ct=default){var x=await repo.GetByIdAsync(c.Id,ct);if(x is null||x.IsDeleted)return Result.Failure(ContentErrors.TaxonomyNotFound);var before=ContentAuditSnapshots.From(x);var slug=string.IsNullOrWhiteSpace(c.Slug)?x.Slug:slugs.Generate(c.Slug);if(await repo.ExistsBySlugAsync(x.SiteKey,x.Kind,slug,x.Id,ct))return Result.Failure(ContentErrors.TaxonomySlugAlreadyExists);x.Update(c.Name,slug,c.Description,c.ParentId,c.SortOrder,c.ActorUserId);await audit.PublishAsync(new ContentAuditEvent(ContentAuditEventTypes.TaxonomyUpdated,ContentAuditActions.Updated,ContentAuditEntityTypes.TaxonomyTerm,x.Id,c.ActorUserId,Before:before,After:ContentAuditSnapshots.From(x)),ct);await uow.SaveChangesAsync(ct);return Result.Success();}}
